// Browser fetch protocol with generated bytes, not actual ToonCN images.
import assert from 'node:assert/strict';
import {fetchReaderImage} from '../extensions/tooncn_bridge/image.mjs';
const page='https://tooncn.net/123-Ep-1/',source='https://tooncn.net/wp-content/uploads/fixture/0001.jpg';
globalThis.location=new URL(page);
globalThis.document={querySelectorAll:selector=>{assert.equal(selector,'#readerarea img.ts-main-image');return [{getAttribute:k=>k==='data-src'?source+'?not_exported=private':null,currentSrc:''}];}};
let calls=0;
globalThis.fetch=async(url,options)=>{calls++;assert.equal(options.credentials,'same-origin');assert.equal(options.redirect,'error');return {status:200,headers:{get:n=>({'Content-Type':'image/jpeg','Content-Length':'3'}[n]||null)},body:{getReader:()=>{let done=false;return {read:async()=>done?{done:true}:(done=true,{done:false,value:new Uint8Array([1,2,3])})};}}};};
let out=await fetchReaderImage(page,source);assert.equal(out.ok,true);assert.equal(out.bytes,3);assert.equal(out.base64,'AQID');assert(!JSON.stringify(out).includes('private'));
out=await fetchReaderImage(page,'https://other.example/a.jpg');assert.equal(out.code,'IMAGE_SOURCE_CHANGED');assert.equal(calls,1);
globalThis.fetch=async()=>({status:403});out=await fetchReaderImage(page,source);assert.equal(out.code,'ACCESS_DENIED');
globalThis.fetch=async()=>({status:429});out=await fetchReaderImage(page,source);assert.equal(out.code,'RATE_LIMITED');
console.log('Synthetic same-context image protocol checks passed.');
